// @ts-check
// Generated by Doc Writer. The repository comes from GITHUB_REPOSITORY at build time
// (set by GitHub Actions), so these bytes are the same for every repository.
const fs = require('fs');
const path = require('path');

const [owner, repo] = (process.env.GITHUB_REPOSITORY || 'owner/repo').split('/');
const userSite = repo.toLowerCase() === `${owner.toLowerCase()}.github.io`;
// The navbar title: the repository, or the owner for an <owner>.github.io repository.
const siteName = userSite ? owner : repo;

// Code blocks: Gladiator's docs viewer syntax tokens (colors.css), light and dark. Plain
// objects, so there is nothing to install and nothing fetched.
const prismLight = {
  plain: {color: '#1d2540', backgroundColor: '#f4f6fb'},
  styles: [
    {
      types: ['comment', 'prolog', 'doctype', 'cdata'],
      style: {color: '#686d8b', fontStyle: 'italic'},
    },
    {types: ['keyword', 'atrule', 'important'], style: {color: '#8a3fc0'}},
    {types: ['function', 'class-name', 'tag'], style: {color: '#2563c9'}},
    {
      types: ['string', 'char', 'attr-value', 'template-string', 'inserted'],
      style: {color: '#2f7a30'},
    },
    {types: ['number', 'boolean', 'constant', 'symbol'], style: {color: '#a35600'}},
    {types: ['property', 'attr-name', 'variable'], style: {color: '#0f7490'}},
    {types: ['punctuation', 'operator'], style: {color: '#454c6b'}},
    {types: ['deleted'], style: {color: '#c1303f'}},
  ],
};

const prismDark = {
  plain: {color: '#e8ebf7', backgroundColor: '#070910'},
  styles: [
    {
      types: ['comment', 'prolog', 'doctype', 'cdata'],
      style: {color: '#9aa2c9', fontStyle: 'italic'},
    },
    {types: ['keyword', 'atrule', 'important'], style: {color: '#bb9af7'}},
    {types: ['function', 'class-name', 'tag'], style: {color: '#7aa2f7'}},
    {
      types: ['string', 'char', 'attr-value', 'template-string', 'inserted'],
      style: {color: '#9ece6a'},
    },
    {types: ['number', 'boolean', 'constant', 'symbol'], style: {color: '#ff9e64'}},
    {types: ['property', 'attr-name', 'variable'], style: {color: '#7dcfff'}},
    {types: ['punctuation', 'operator'], style: {color: '#b8bfdc'}},
    {types: ['deleted'], style: {color: '#f7768e'}},
  ],
};

const escapeHtml = (text) =>
  String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

// `/` must always resolve. When index.md is part of the push it owns the root (`slug: /`).
// When it is left out (an internal page is never pushed) no page does, and `/` would be a 404:
// write a small landing that sends the reader to the first page of the sidebar that exists.
// Plain JavaScript run after the build: no React, no extra package, never names a page the
// site does not have (a sidebar entry counts only when the build made a route for it).
function rootLanding() {
  return {
    name: 'doc-writer-root-landing',
    async postBuild({outDir, baseUrl, routesPaths}) {
      const file = path.join(outDir, 'index.html');
      if (fs.existsSync(file)) return;
      const routes = new Set((routesPaths || []).map((r) => r.replace(/[/]+$/, '')));
      const groups = require('./sidebar-items.json').groups || [];
      let target = null;
      for (const group of groups) {
        for (const item of group.items || []) {
          const route = baseUrl + item.id;
          if (target === null && routes.has(route)) target = route;
        }
      }
      const link = target === null ? '' : escapeHtml(target);
      const head =
        target === null
          ? ''
          : `<meta http-equiv="refresh" content="0; url=${link}">` +
            `<link rel="canonical" href="${link}">`;
      const body = target === null
        ? '<p>This site has no pages yet.</p>'
        : `<p><a href="${link}">Open the documentation</a></p>`;
      fs.writeFileSync(
        file,
        '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
          '<meta name="viewport" content="width=device-width, initial-scale=1">' +
          `<title>${escapeHtml(siteName)}</title>${head}` +
          '<style>body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;' +
          'margin:3rem 1.5rem;color:#454c6b;background:#fdfeff}a{color:#1f5ec4}' +
          '@media(prefers-color-scheme:dark){body{color:#b8bfdc;background:#161a24}' +
          'a{color:#5b9dff}}</style>' +
          `</head><body>${body}</body></html>`,
      );
    },
  };
}

/** @type {import('@docusaurus/types').Config} */
module.exports = {
  title: siteName,
  url: `https://${owner.toLowerCase()}.github.io`,
  baseUrl: userSite ? '/' : `/${repo}/`,
  // Links carry no trailing slash: serve /a/b, or Pages answers every click with a 301.
  trailingSlash: false,
  // A page can link one this version does not hold, and an image key may not resolve:
  // the branch is Doc Writer's, so the customer cannot fix the page. Warn, never fail the build.
  onBrokenLinks: 'warn',
  // The pages are Markdown, not MDX: text such as `<TOKEN>` must not fail the build.
  markdown: {
    format: 'detect',
    hooks: {onBrokenMarkdownLinks: 'warn', onBrokenMarkdownImages: 'warn'},
  },
  plugins: [rootLanding],
  themeConfig: {
    colorMode: {respectPrefersColorScheme: true},
    navbar: {title: siteName},
    prism: {theme: prismLight, darkTheme: prismDark},
  },
  presets: [
    [
      'classic',
      {
        // index.md has `slug: /`, so the docs own the site root.
        docs: {path: 'docs', routeBasePath: '/', sidebarPath: require.resolve('./sidebars.js')},
        blog: false,
        theme: {customCss: require.resolve('./src/css/custom.css')},
      },
    ],
  ],
};
